import type { ConnectorRoutingMode } from "./connectorRouting.ts";

export type TopologySceneLayout = "viewport-fit" | "world-grid";
export type TopologyLayoutMode = "ring" | "linear" | "fishspine" | "radial-sectors" | "orbital-clusters" | "spiral" | "cascade-tree" | "swimlanes" | "fan" | "matrix" | "basin" | "paired-comparison" | "territories" | "custom";
export type TopologyCameraPersistence = "none" | "session" | "local";

export const TOPOLOGY_LAYOUT_PREFERRED_CONNECTOR_ROUTING: Record<
  TopologyLayoutMode,
  ConnectorRoutingMode
> = {
  ring: "obstacle-aware",
  linear: "straight",
  fishspine: "straight",
  "radial-sectors": "obstacle-aware",
  "orbital-clusters": "obstacle-aware",
  spiral: "obstacle-aware",
  "cascade-tree": "obstacle-aware",
  swimlanes: "obstacle-aware",
  fan: "straight",
  matrix: "obstacle-aware",
  basin: "obstacle-aware",
  "paired-comparison": "obstacle-aware",
  territories: "obstacle-aware",
  custom: "obstacle-aware",
};

export function resolveTopologyLayoutConnectorRouting(
  topologyLayout: TopologyLayoutMode,
): ConnectorRoutingMode {
  return TOPOLOGY_LAYOUT_PREFERRED_CONNECTOR_ROUTING[topologyLayout];
}

export interface TopologySceneConfig {
  layout: TopologySceneLayout;
  radius: number;
  columns: number;
  rows: number;
  originQ: number;
  originR: number;
  showGridNodes: boolean;
  viewportFit: boolean;
  gridActivity: boolean;
  ambientSignals: boolean;
  connectorRouting: ConnectorRoutingMode;
  topologyLayout: TopologyLayoutMode;
}

export interface TopologyCameraConfig {
  zoomStep: number;
  keyboardPanStep: number;
  edgePanThreshold: number;
  edgePanSpeed: number;
  persistence: TopologyCameraPersistence;
  transitionDuration: number;
  safeAreaRatio: number;
}

export interface TopologySignalConfig {
  transitionSpeed: number;
}

export interface TopologyMiniMapConfig {
  enabled: boolean;
  interactive: boolean;
  showControls: boolean;
}

export interface TopologyPageConfig {
  scene: TopologySceneConfig;
  camera: TopologyCameraConfig;
  signal: TopologySignalConfig;
  minimap: TopologyMiniMapConfig;
}

export function createTopologySceneConfig(
  config: Omit<TopologySceneConfig, "viewportFit" | "connectorRouting" | "topologyLayout"> & {
    viewportFit?: boolean;
    connectorRouting?: ConnectorRoutingMode;
    topologyLayout?: TopologyLayoutMode;
  },
): TopologySceneConfig {
  const viewportFit = config.viewportFit ?? config.layout === "viewport-fit";
  const connectorRouting =
    config.connectorRouting ??
    resolveTopologyLayoutConnectorRouting(config.topologyLayout ?? "custom");

  return {
    ...config,
    viewportFit,
    connectorRouting,
    topologyLayout: config.topologyLayout ?? "custom",
  };
}

